# Shopping Cart Component with Redux Toolkit

Here's a complete shopping cart component with Redux Toolkit for state management:

```jsx
// src/store/cartSlice.js
import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  items: [],
  total: 0,
  quantity: 0,
};

export const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addItem: (state, action) => {
      const item = action.payload;
      const existingItem = state.items.find(i => i.id === item.id);

      if (existingItem) {
        existingItem.quantity += item.quantity;
      } else {
        state.items.push({ ...item, quantity: item.quantity });
      }

      // Recalculate total and quantity
      state.total = state.items.reduce((sum, item) => sum + (item.price * item.quantity), 0);
      state.quantity = state.items.reduce((sum, item) => sum + item.quantity, 0);
    },
    removeItem: (state, action) => {
      const itemId = action.payload;
      state.items = state.items.filter(item => item.id !== itemId);

      // Recalculate total and quantity
      state.total = state.items.reduce((sum, item) => sum + (item.price * item.quantity), 0);
      state.quantity = state.items.reduce((sum, item) => sum + item.quantity, 0);
    },
    updateQuantity: (state, action) => {
      const { id, quantity } = action.payload;

      const item = state.items.find(item => item.id === id);
      if (item) {
        item.quantity = quantity;

        // Recalculate total and quantity
        state.total = state.items.reduce((sum, item) => sum + (item.price * item.quantity), 0);
        state.quantity = state.items.reduce((sum, item) => sum + item.quantity, 0);
      }
    },
    clearCart: (state) => {
      state.items = [];
      state.total = 0;
      state.quantity = 0;
    }
  }
});

export const { addItem, removeItem, updateQuantity, clearCart } = cartSlice.actions;

export default cartSlice.reducer;
```

